## HOME
location = / {
    rewrite ^ https://ip2country.info$request_uri? permanent;
}


## REQUEST
location = "/ip" {

    ## NO IP?
    if ( $ip = "" ) {
        return 400;
    }

    ## METHOD LIMIT
    limit_except GET {
        deny all;
    }

    ## REQUESTS LIMIT
    limit_req zone=api_req_zone burst=100 nodelay;

    ## PROXY
    proxy_cache api_cache_zone;
    proxy_cache_min_uses 2;
    proxy_cache_valid 1h;
    proxy_cache_use_stale error timeout updating http_500 http_502 http_503 http_504;
    proxy_cache_lock on;

    proxy_pass $upstream_server;
    proxy_set_body none;
    proxy_redirect off;
    proxy_http_version 1.1;
    proxy_pass_request_headers off;
    proxy_set_header X-Forwarded-For $ip;

    ## HEADERS
    add_header X-Robots-Tag noindex;
    add_header X-Frame-Options deny;
    add_header X-Content-Type-Options nosniff;
    add_header X-XSS-Protection "1; mode=block";
    add_header X-Cache-Status $upstream_cache_status;

    add_header Access-Control-Allow-Origin *;
    add_header Access-Control-Allow-Methods "GET, HEAD";
    add_header Strict-Transport-Security "max-age=31536000";
    add_header Cache-Control "max-age=0, private, must-revalidate";
}


## ROBOTS
location = "/robots.txt" {
    expires 31d;
    access_log off;

    echo 'User-agent: *';
    echo 'Disallow: /';

    add_header Cache-Control public;
    add_header X-Robots-Tag noindex;
}

## UPSTREAMS
upstream api_server_head {
    server 127.0.0.1:7788;
}
upstream api_server_get {
    server 127.0.0.1:8899;
}


## HTTP
server {
    ## INIT
    listen 80;
    listen [::]:80;


    ## SERVER NAME
    server_name api.ip2country.info;


    ## REWRITE
    rewrite ^ https://api.ip2country.info$request_uri? permanent;
}


## HTTPS
server {
    ## INIT
    listen 443 ssl;
    listen [::]:443 ssl;


    ## SERVER NAME
    server_name api.ip2country.info;


    ## WWW REDIRECT
    if ( $http_host != api.ip2country.info ) {
        rewrite ^ https://api.ip2country.info$request_uri? permanent;
    }


    ## INCLUDES
    include conf.d/security.rules;
    include conf.d/ssl.rules;
    include conf.d/api.rules;
    include conf.d/default.rules;


    ## ROOT
    root /var/www/ip2country.info;


    ## LOGS
    access_log /var/log/nginx/access-api.log api_access_log if=$is_not_runscope;
}


## GET REQUESTS
server {
    ## INIT
    listen 8899;


    ## SECURITY
    allow 127.0.0.1;
    deny all;


    ## LOGS
    access_log off;


    ## MIME TYPE
    default_type "application/json; charset=utf-8";


    ## OUTPUT
    location / {
        echo "{";
        echo '\t"countryCode": "$geoip_country_code",';
        echo '\t"countryCode3": "$geoip_country_code3",';
        echo '\t"countryName": "$geoip_country_name",';
        echo '\t"countryEmoji": "$geoip_country_emoji"';
        echo "}";
    }
}


## HEAD REQUESTS
server {
    ## INIT
    listen 7788;


    ## SECURITY
    allow 127.0.0.1;
    deny all;


    ## LOGS
    access_log off;


    ## OUTPUT
    location / {
        add_header X-Country-Code "$geoip_country_code";
        add_header X-Country-Code3 "$geoip_country_code3";
        add_header X-Country-Name "$geoip_country_name";

        echo_flush;
    }
}

/*
* Load plugins
*/

const
    gulp = require('gulp'),
    sass = require('gulp-sass'),
    notify = require('gulp-notify'),
    inline = require('gulp-inline'),
    htmlmin = require('gulp-htmlmin'),
    cleanCSS = require('gulp-clean-css'),
    htmlhint = require('gulp-htmlhint'),
    multipipe = require('multipipe'),
    zopfli = require('gulp-zopfli'),
    config = require('./config.json'),
    sourcemaps = require('gulp-sourcemaps'),
    stylelint = require('gulp-stylelint'),
    browserSync = require('browser-sync').create();


/*
* SCSS tasks
*/

gulp.task( 'scss:build', () => {
    return multipipe(
        gulp.src( config.scss.source ),

        sourcemaps.init(),
        stylelint( { reporters: [ { formatter: 'string', console: true } ] } ),
        sass(),
        sourcemaps.write( '.', { includeContent: false, sourceRoot: config.scss.root } ),

        gulp.dest( config.css.path ),
        browserSync.stream()
    ).on( 'error', notify.onError() );
} );


/*
* HTML tasks
*/

gulp.task( 'html:hint', () => {
    return multipipe(
        gulp.src( config.html.source ),

        htmlhint(),
        htmlhint.failReporter(),

        gulp.dest( config.html.path )
    ).on( 'error', notify.onError() );
} );

gulp.task( 'html:inline', [ 'html:hint' ], () => {
    return multipipe(
        gulp.src( config.html.source ),

        inline( { base: '.', css: cleanCSS } ),

        gulp.dest( config.dest.path )
    ).on( 'error', notify.onError() );
} );

gulp.task( 'html:minify', [ 'html:inline' ], () => {
    return multipipe(
        gulp.src( config.dest.path + config.html.source ),

        htmlmin( {
            collapseWhitespace: true,
            removeRedundantAttributes: true,
            removeOptionalTags: true,
            removeAttributeQuotes: true,
            collapseBooleanAttributes: true
        } ),

        gulp.dest( config.dest.path )
    ).on( 'error', notify.onError() );
} );

gulp.task( 'html:compress', [ 'scss:build', 'html:minify' ], () => {
    return multipipe(
        gulp.src( config.dest.path + config.html.source ),

        zopfli(),

        gulp.dest( config.dest.path )
    ).on( 'error', notify.onError() );
} );


/*
* Copy task
*/

gulp.task( 'copy:files', () => {
    return multipipe(
        gulp.src( config.copy.files ),

        gulp.dest( config.dest.path )
    ).on( 'error', notify.onError() );
});


/*
* browserSync task
*/

gulp.task('serve', [ 'scss:build' ], () => {
    browserSync.init( {
        server: true,
        port: 3001,
        browser: 'google chrome'
    } );

    gulp.watch( config.scss.source, [ 'scss:build' ] );
    gulp.watch( config.html.source, [ 'html:hint' ], browserSync.reload );
});


/*
* Build task
*/

gulp.task( 'build', [ 'scss:build', 'html:compress', 'copy:files' ] );


/*
* Default task
*/

gulp.task( 'default', [ 'serve' ] );
